<?php
require_once 'config/database.php';
require_once 'includes/functions.php';
$restaurant_id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: 0;
$osm_id = trim($_GET['osm_id'] ?? $_GET['place_id'] ?? '');
$page_title = 'Restaurant details';
include 'includes/header.php';
?>
<section class="page-banner"><div class="container"><div class="eyebrow">FoodNest restaurant</div><div id="restaurant-detail-heading"><h1>Loading restaurant...</h1><p class="muted">Loading verified restaurant details.</p></div></div></section>
<section class="section"><div class="container"><div id="restaurant-detail" class="restaurant-detail-layout"><div class="empty-state"><h3>Loading details...</h3></div></div><div class="section-heading menu-heading"><div><div class="eyebrow">Menu</div><h2>Available menu</h2></div></div><div id="restaurant-menu" class="food-grid"><div class="empty-state"><h3>Checking menu availability...</h3></div></div></div></section>
<script>
const detailsQuery = <?= json_encode($restaurant_id ? ['id' => $restaurant_id] : ['osm_id' => $osm_id]) ?>;
function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[character]));}
function imageMarkup(image,name){return image?`<img class="restaurant-detail-photo" src="${escapeHtml(image)}" alt="${escapeHtml(name)}" onerror="this.replaceWith(Object.assign(document.createElement('div'),{className:'restaurant-detail-photo detail-placeholder',textContent:'No restaurant image available'}))">`:'<div class="restaurant-detail-photo detail-placeholder">No restaurant image available</div>';}
function menuMarkup(place){if(!place.menu_available||!place.foods?.length)return `<div class="empty-state"><h3>Menu information is currently unavailable.</h3><p>${escapeHtml(place.menu_message||'This restaurant has no FoodNest menu data.')}</p></div>`;let groups={};place.foods.forEach(food=>(groups[food.category_name]??=[]).push(food));return Object.entries(groups).map(([category,foods])=>`<div class="menu-group"><h3>${escapeHtml(category)}</h3><div class="food-grid">${foods.map(food=>`<article class="food-card"><img src="${escapeHtml(food.image)}" alt="${escapeHtml(food.food_name)}"><div class="food-info"><h3>${escapeHtml(food.food_name)}</h3><p>${escapeHtml(food.description)}</p><div class="food-meta"><span class="price">₹${Number(food.price).toFixed(2)}</span>${Number(food.availability)?`<button class="small" onclick="addToCart(${Number(food.food_id)},${Number(place.id)})">Add</button>`:'<span class="availability off">Unavailable</span>'}</div></div></article>`).join('')}</div></div>`).join('');}
async function loadDetails(){const query=new URLSearchParams(detailsQuery);const response=await fetch(`api/restaurant_details.php?${query}`);const result=await response.json();if(!result.success){document.querySelector('#restaurant-detail-heading').innerHTML=`<h1>Unable to load restaurant</h1><p class="error">${escapeHtml(result.message)}</p>`;document.querySelector('#restaurant-detail').innerHTML='';document.querySelector('#restaurant-menu').innerHTML='';return;}const place=result.restaurant;document.title=`${place.name} | FoodNest`;document.querySelector('#restaurant-detail-heading').innerHTML=`<h1>${escapeHtml(place.name)}</h1><p class="muted">${escapeHtml(place.address)}</p>`;const rating=place.rating===null?'Rating not available':`★ ${Number(place.rating).toFixed(1)}`;const status=place.is_open===null?'Status not available':(place.is_open?'Open now':'Closed now');document.querySelector('#restaurant-detail').innerHTML=`${imageMarkup(place.image,place.name)}<div class="restaurant-detail-copy"><div class="restaurant-detail-meta"><span>${escapeHtml(rating)}</span><span>${escapeHtml(place.cuisine||'Restaurant')}</span><span class="${place.is_open?'open':'closed'}">${status}</span></div><p>${escapeHtml(place.address)}</p>${place.phone?`<p>Phone: ${escapeHtml(place.phone)}</p>`:''}${place.opening_hours?`<p>Hours: ${escapeHtml(place.opening_hours)}</p>`:''}</div>`;document.querySelector('#restaurant-menu').innerHTML=menuMarkup(place);}
loadDetails();
</script>
<?php include 'includes/footer.php'; ?>
